#include "zari/app.hpp"
#include <iostream>
int main(int argc,char**argv){std::string error;auto cli=zari::parse_cli(argc,argv,error);if(!cli){std::cerr<<"zari: "<<error<<"\nTry 'zari --help'.\n";return 2;}if(cli->help){std::cout<<"Zari "<<ZARI_VERSION<<" — keyboard-driven terminal file manager\n\nUsage:\n  zari [OPTIONS] [PATH]\n  zari init\n\nCommands:\n  init                Create default config files without overwriting existing files\n\nOptions:\n  -h, --help          Show this help\n  -V, --version       Show version\n      --config PATH   Use a specific zari.toml\n      --theme NAME    Select a built-in theme\n      --debug         Enable diagnostic logging\n\nNavigation:\n  h                   Go to the parent directory\n  b / B               Go back / forward in directory history\n  ?                   Show all active keybindings\n";return 0;}if(cli->version){std::cout<<"zari "<<ZARI_VERSION<<'\n';return 0;}if(cli->init){auto directory=zari::config_directory();auto result=zari::initialize_config(directory);if(!result.error.empty()){std::cerr<<"zari: "<<result.error<<'\n';return 1;}std::cout<<"Zari configuration: "<<directory.string()<<'\n';for(const auto&path:result.created)std::cout<<"  created "<<path.filename().string()<<'\n';for(const auto&path:result.existing)std::cout<<"  kept    "<<path.filename().string()<<" (already exists)\n";return 0;}try{return zari::App(*cli).run();}catch(const std::exception&e){std::cerr<<"zari: "<<e.what()<<'\n';return 1;}}
